import json
import adapter_kit

def adapt(path):
    try:
        coords = adapter_kit.read_coordinates(path)
    except Exception:
        coords = []
    lines = []
    if coords:
        lines.append('Coordinate pairs (latitude, longitude): %d' % len(coords))
        for i, pair in enumerate(coords[:20], 1):
            try:
                lat, lon = pair
                lines.append('%d. Latitude: %s; longitude: %s' % (i, lat, lon))
                try:
                    summary = adapter_kit.coordinate_summary(lat, lon)
                    if summary is not None:
                        lines.append('Geographic context: ' + json.dumps(summary, ensure_ascii=False, default=str))
                except Exception:
                    pass
                try:
                    places = adapter_kit.nearest_places(lat, lon)
                    if places is not None:
                        lines.append('Nearby places: ' + json.dumps(places, ensure_ascii=False, default=str))
                except Exception:
                    pass
            except Exception:
                continue
    else:
        try:
            with open(path, 'rb') as f:
                raw = f.read(4096)
            lines.append('File content: ' + raw.decode('utf-8', errors='replace'))
        except Exception:
            lines.append('Coordinate content could not be read.')
    return {'text': '\n'.join(lines)[:4000]}
